<?php
require_once __DIR__.'/../includes/bootstrap.php';require_role('assessor');$user=current_user();$flashes=render_flashes();$currentPage='assessments';$pageTitle='Assessment Queue';require_once __DIR__.'/_helpers.php';$conn=Database::getConnection();$assessorId=(int)($user['id']??$user['user_id']??0);if($assessorId<=0){http_response_code(403);exit('Invalid Assessor account.');}$search=trim((string)($_GET['search']??''));$status=trim((string)($_GET['status']??''));$rows=[];
if(as_has_table($conn,'assessment_attempts')){$w=['aa.assessor_id=?'];$p=[$assessorId];$t='i';if($search!==''){$w[]="(u.first_name LIKE ? OR u.last_name LIKE ? OR u.email LIKE ? OR ao.title LIKE ? OR ao.code LIKE ?)";$like='%'.$search.'%';for($i=0;$i<5;$i++)$p[]=$like;$t.='sssss';}if($status!==''){$w[]='aa.status=?';$p[]=$status;$t.='s';}$sql="SELECT aa.id attempt_id,aa.attempt_number,aa.status,aa.submitted_at,u.first_name,u.last_name,u.email,ao.code outcome_code,ao.title outcome_title,(SELECT COUNT(*) FROM assessment_criteria ac WHERE ac.outcome_id=ao.id AND ac.is_active=1) criterion_count,(SELECT COUNT(*) FROM assessment_decisions ad WHERE ad.attempt_id=aa.id AND ad.assessor_id=aa.assessor_id) decision_count FROM assessment_attempts aa JOIN users u ON u.id=aa.participant_id JOIN assessment_outcomes ao ON ao.id=aa.outcome_id WHERE ".implode(' AND ',$w)." ORDER BY CASE WHEN aa.status='submitted' THEN 0 WHEN aa.status='in_review' THEN 1 ELSE 2 END,aa.submitted_at DESC";$s=$conn->prepare($sql);if($s){$s->bind_param($t,...$p);$s->execute();$r=$s->get_result();while($x=$r->fetch_assoc())$rows[]=$x;$s->close();}}
require __DIR__.'/_layout_start.php';?>
<div class="as-page-header"><div><span class="as-page-header__eyebrow">Assessment Workflow</span><h2>Assessment Queue</h2><p>Review evidence submitted against outcomes and make criterion-level assessment decisions.</p></div></div>
<form class="as-filter" method="get"><div class="as-field as-field--grow"><label for="search">Search</label><div class="as-input-icon"><i class="fas fa-magnifying-glass"></i><input id="search" name="search" value="<?= e($search) ?>" placeholder="Participant, email, outcome or code"></div></div><div class="as-field"><label for="status">Status</label><select id="status" name="status"><option value="">All statuses</option><?php foreach(['submitted','in_review','awaiting_moderation','final_approved','resubmission_required'] as $x):?><option value="<?= e($x) ?>" <?= $status===$x?'selected':'' ?>><?= e(as_label($x)) ?></option><?php endforeach;?></select></div><div class="as-filter__actions"><button class="as-btn as-btn--primary"><i class="fas fa-filter"></i> Apply</button><a class="as-btn as-btn--secondary" href="<?= url('assessor/assessments.php') ?>">Reset</a></div></form>
<div class="as-card"><div class="as-card__header"><div><h3>Assigned Assessment Attempts</h3><p><?= number_format(count($rows)) ?> record(s) found.</p></div></div><?php if(!$rows):?><div class="as-empty"><div class="as-empty__icon"><i class="fas fa-clipboard-check"></i></div><strong>No assessments found</strong><span>No assigned assessment attempt matched your filters.</span></div><?php else:?><div class="as-table-wrap"><table class="as-table"><thead><tr><th>Participant</th><th>Outcome</th><th>Attempt</th><th>Status</th><th>Criteria</th><th>Submitted</th><th></th></tr></thead><tbody><?php foreach($rows as $x):$f=trim((string)$x['first_name']);$l=trim((string)$x['last_name']);$pr=as_percent((int)$x['decision_count'],(int)$x['criterion_count']);?><tr><td><div class="as-person"><div class="as-avatar"><?= e(as_initials($f,$l)) ?></div><div><strong><?= e(trim($f.' '.$l)?:'Participant') ?></strong><span><?= e($x['email']) ?></span></div></div></td><td><strong><?= e($x['outcome_code']) ?></strong><span class="as-table-sub"><?= e($x['outcome_title']) ?></span></td><td>#<?= (int)$x['attempt_number'] ?></td><td><span class="as-status as-status--<?= e(as_class($x['status'])) ?>"><?= e(as_label($x['status'])) ?></span></td><td><div class="as-progress as-progress--table"><div class="as-progress__labels"><span><?= (int)$x['decision_count'] ?>/<?= (int)$x['criterion_count'] ?></span><strong><?= $pr ?>%</strong></div><div class="as-progress__track"><span style="width:<?= $pr ?>%"></span></div></div></td><td><?= e(as_datetime($x['submitted_at'])) ?></td><td class="as-table__action"><a class="as-btn as-btn--primary as-btn--small" href="<?= url('assessor/review_assessment.php?id='.(int)$x['attempt_id']) ?>">Review <i class="fas fa-arrow-right"></i></a></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div>
<?php require __DIR__.'/_layout_end.php';?>
